def _heading(number, title, description):
    st.markdown(f'<header class="wf-heading"><span class="wf-heading__number">{number:02d}</span><div class="wf-heading__content"><h2>{escape(title)}</h2>'
                f'<p>{escape(description)}</p></div></header>', unsafe_allow_html=True)


def _new_draft(kind):
    return {"kind": kind, "epoch": uuid4().hex[:10], "transaction_id": f"{kind.upper()}-{uuid4().hex}",
            "fields": {}, "snapshots": {}}


def _draft(kind):
    durable_key = f"workflow_{kind}_draft"
    if durable_key not in st.session_state:
        st.session_state[durable_key] = _new_draft(kind)
    return st.session_state[durable_key]


def _reset(kind):
    st.session_state[f"workflow_{kind}_draft"] = _new_draft(kind)


def _can_write():
    return bool(st.session_state.get("portal_can_write", True))


def _finish_transaction(kind, result):
    st.cache_data.clear()
    quantity = result.get("total_quantity")
    label = "การแพ็ก" if kind == "packing" else "การส่งสินค้า"
    amount = f" · {_fmt(quantity)} g" if quantity is not None else ""
    st.session_state[f"workflow_{kind}_flash"] = f"ยืนยันผลบันทึก{label}แล้ว{amount}"
    _reset(kind)
    st.rerun()


def _replay(sh, draft):
    attempt = draft["attempt"]
    payload = deepcopy(attempt["payload"])
    if attempt["kind"] == "PACK":
        return pack_inventory(sh, draft["transaction_id"], **payload)
    return ship_inventory(sh, draft["transaction_id"], **payload)


def _recover_pending(sh, draft):
    """Resolve the original payload before any fresh-stock UI can block retry."""
    attempt = draft.get("attempt")
    if not attempt:
        return False
    receipt_error = None
    try:
        result = get_transaction_result(sh, draft["transaction_id"], attempt["kind"], attempt["payload"])
    except Exception as error:
        receipt_error = error
    else:
        if result is not None:
            _finish_transaction(draft["kind"], result)
    st.warning("ยังต้องยืนยันผลของรายการที่กดบันทึกไว้ ระบบเก็บข้อมูลและหมายเลขเดิมไว้เพื่อป้องกันบันทึกซ้ำ")
    if receipt_error is not None:
        st.caption(f"ยังตรวจผลบันทึกไม่ได้: {receipt_error}")
    st.caption("กรุณาตรวจผลรายการเดิมให้เสร็จก่อนเริ่มรายการใหม่ ข้อมูลที่กรอกยังคงอยู่")
    left, right = st.columns(2, gap="large")
    with left:
        if st.button("ตรวจสอบสถานะอีกครั้ง", key=f"{draft['kind']}_check_pending", width="stretch"):
            st.rerun()
    with right:
        if st.button("ลองบันทึกรายการเดิมอีกครั้ง", key=f"{draft['kind']}_replay_pending", type="primary",
                     disabled=not _can_write(), width="stretch"):
            try:
                result = _replay(sh, draft)
            except ValidationError as error:
                # A checked validation failure occurs before a new commit.
                # Keep input fields, but let the user repair that draft.
                draft.pop("attempt", None)
                st.session_state[f"workflow_{draft['kind']}_retry_error"] = str(error)
                st.rerun()
            except Exception as error:
                st.error(f"ยังยืนยันผลบันทึกไม่ได้: {error}")
            else:
                _finish_transaction(draft["kind"], result)
    return True


def _widget_key(draft, name, default):
    widget_key = f"wf_{draft['kind']}_{draft['epoch']}_{name}"
    if widget_key not in st.session_state:
        st.session_state[widget_key] = draft["fields"].get(name, default)
    return widget_key


def _input(draft, name, label, default="", **kwargs):
    result = st.text_input(label, key=_widget_key(draft, name, default), **kwargs)
    draft["fields"][name] = result
    return result


def _area(draft, name, label, default="", **kwargs):
    result = st.text_area(label, key=_widget_key(draft, name, default), **kwargs)
    draft["fields"][name] = result
    return result


def _number(draft, name, label, default=0.0, **kwargs):
    result = st.number_input(label, value=None, key=_widget_key(draft, name, default), **kwargs)
    result = default if result is None else result
    draft["fields"][name] = result
    return result


def _date(draft, name, label, default=None):
    result = st.date_input(label, value=None, key=_widget_key(draft, name, default or today_bangkok()))
    draft["fields"][name] = result
    return result


def _select(draft, name, label, options, default=None, format_func=None, **kwargs):
    options = list(options)
    default = default if default is not None else (options[0] if options else None)
    widget_key = _widget_key(draft, name, default)
    selected = st.session_state.get(widget_key)
    if selected is not None and selected not in options:
        options.append(selected)
    result = st.selectbox(label, options, index=None, key=widget_key,
                          format_func=format_func or (lambda value: str(value)), **kwargs)
    draft["fields"][name] = result
    return result


def _multi(draft, name, label, options, format_func=None):
    options = list(options)
    widget_key = _widget_key(draft, name, [])
    for selected in st.session_state.get(widget_key, []):
        if selected not in options:
            options.append(selected)
    result = st.multiselect(label, options, key=widget_key, format_func=format_func or (lambda value: str(value)))
    draft["fields"][name] = list(result)
    return result


def _fmt(value):
    try:
        return "—" if pd.isna(value) else f"{float(value):,.0f}"
    except (ValueError, TypeError):
        return "—"


def _stock_label(item):
    return (f"{item.get('cultivar') or 'ไม่ระบุสายพันธุ์'} · Lot {item.get('lot') or 'ไม่ระบุ'} · "
            f"{item.get('grade') or '—'} · {_fmt(item.get('quantity'))} g · {item.get('supplier') or 'ไม่ระบุ Supplier'}")


def _numeric_frame(rows):
    frame = pd.DataFrame(rows).copy()
    for column in frame:
        if column in {"Quantity", "Waste Qty", "Total Packed Qty", "Shipped Qty", "Produced Qty", "Initial Qty", "Shipped Volume", "Volume"}:
            frame[column] = pd.to_numeric(frame[column].astype(str).str.replace(",", "", regex=False), errors="coerce")
    return frame


def _render_table(frame, *, columns=None, height=None):
    if frame.empty:
        st.caption("ยังไม่มีรายการในช่วงที่เลือก")
        return
    if columns:
        frame = frame[[column for column in columns if column in frame]]
    options = {"height": height} if height is not None else {}
    render_numeric_dataframe(frame, width="stretch", hide_index=True, **options)


def render_numeric_dataframe(data, *, column_config=None, **kwargs):
    """Format numeric cells only; retain numeric sorting and original precision."""
    frame = data if isinstance(data, pd.DataFrame) else data.data
    config = dict(column_config or {})
    for column in frame:
        if not pd.api.types.is_numeric_dtype(frame[column]) or pd.api.types.is_bool_dtype(frame[column]):
            continue
        if column in config and config[column] is None:
            continue
        previous = config.get(column)
        if isinstance(previous, dict):
            previous = dict(previous)
            settings = dict(previous.get("type_config") or {})
            if settings.get("type", "number") != "number":
                continue
            settings.update(type="number", format="%,.0f")
            previous["type_config"] = settings
            config[column] = previous
        else:
            config[column] = st.column_config.NumberColumn(previous or str(column), format="%,.0f")
    return st.dataframe(data, column_config=config, **kwargs)


def first_display_lot(value):
    """Read the first lot in the cell, preserving the sheet's original order."""
    raw = text(value)
    if key(raw) in {"n/a", "na", "tbc", "tbd", "-", "—"}:
        return raw
    return next((part.strip() for part in re.split(r"[,;|+/\\r\\n]+", raw) if part.strip()), "")


def fg_display_lot(value):
    """Strip only the terminal packing sequence and grade; stored lot is intact."""
    return re.sub(r"-FG\\d+-[^\\r\\n]+$", "", first_display_lot(value), flags=re.IGNORECASE)


def delivery_internal_lots(frame, main_records, packing_records):
    """Propose WIP/FG lots from Sheet 1, then Source WIP Lot for missing FG."""
    normalize = lambda value: "".join(character for character in key(value) if character.isalnum())
    unknown = {"", "tbc", "tbd", "na", "none"}

    def field(record, aliases):
        for alias in aliases:
            for header, value in record.items():
                if normalize(header) == normalize(alias) and text(value):
                    return text(value)
        return ""

    cultivar_aliases = ("Cultivar Name", "Cultivar", "Cultivar / Product", "Product", "สายพันธุ์", "ชื่อสายพันธุ์")

    def names(record):
        return {value for value in (normalize(field(record, cultivar_aliases)),
                                   normalize(field(record, ("Export Name",)))) if value not in unknown}

    def internal(record):
        return field(record, ("THAI STICK Lot. No.",))

    def tokens(value):
        return {key(part) for part in re.split(r"[,;|+/\\r\\n]+", text(value)) if normalize(part) not in unknown}

    def first_internal(records):
        for record in records:
            lot = first_display_lot(internal(record))
            if normalize(lot) not in unknown:
                return lot
        return ""

    def resolve(row):
        wanted = normalize(field(row, cultivar_aliases + ("Export Name",)))
        if wanted in unknown:
            return "—", "—"
        matching = [record for record in main_records if wanted in names(record)]
        wip_records = [record for record in matching if normalize(field(record, ("Category",))).startswith("wip")]
        fg_records = [record for record in matching if normalize(field(record, ("Category",))).startswith("fg")]
        wip = first_internal(wip_records)
        fg = first_internal(fg_records)
        if not fg:
            source_lots = set().union(*(tokens(internal(record)) for record in wip_records))
            wanted_names = {wanted}.union(*(names(record) for record in matching))
            for record in packing_records:
                source = field(record, ("Source WIP Lot", "Source WIP Lot No."))
                if not source:
                    continue
                identities = names(record)
                # Named packing rows must match their own cultivar. Only unnamed
                # rows use the join: cultivar -> Sheet 1 WIP lot -> source lot.
                matches = bool(wanted_names & identities) or (not identities and bool(source_lots & tokens(source)))
                if not identities and normalize(source) == wanted:
                    matches = True
                if matches:
                    fg = first_display_lot(source)
                    break
        return wip or "—", fg or "—"

    lot_columns = [column for column in frame if normalize(column) in {
        "lot", "lotno", "supplierlotno", "thaisticklotno", "generatedfglotno", "wiplotno", "fglotno"}]
    position = min((list(frame.columns).index(column) for column in lot_columns), default=len(frame.columns))
    result = frame.drop(columns=lot_columns).copy()
    proposals = [resolve(row) for row in frame.to_dict("records")]
    result.insert(min(position, len(result.columns)), "WIP Lot No.", [value[0] for value in proposals])
    result.insert(min(position + 1, len(result.columns)), "FG Lot No.", [value[1] for value in proposals])
    return result


def _parse_optional(value):
    try:
        return parse_date(value, allow_pending=True)
    except (ValueError, TypeError):
        return None


def _history(sh, sheet_name, title, prefix):
    st.divider()
    st.subheader(title)
    try:
        rows = read_history(sh, sheet_name)
    except Exception as error:
        st.error(f"โหลดประวัติไม่สำเร็จ: {error}")
        return
    if not rows:
        st.caption("ยังไม่มีประวัติ")
        return
    frame = _numeric_frame(rows)
    date_column = "Packing Date" if "Packing Date" in frame else "Shipment Date" if "Shipment Date" in frame else "Timestamp"
    dates = frame.get(date_column, pd.Series("", index=frame.index)).map(_parse_optional)
    first, last = st.columns([2, 1], gap="large")
    with first:
        query = st.text_input("ค้นหา Lot, สายพันธุ์, Supplier หรือผู้รับ", key=f"{prefix}_history_search")
    with last:
        period = st.date_input("ช่วงวันที่", value=[], key=f"{prefix}_history_period")
    mask = pd.Series(True, index=frame.index)
    if query.strip():
        searchable = frame.fillna("").astype(str).agg(" ".join, axis=1)
        mask &= searchable.str.casefold().str.contains(query.strip().casefold(), regex=False)
    if isinstance(period, (tuple, list)) and len(period) == 2:
        start, end = period
        if start > end:
            st.warning("กรุณาเลือกวันเริ่มต้นก่อนวันสิ้นสุด")
            return
        mask &= dates.map(lambda value: value is not None and start <= value <= end)
    selected = frame[mask].copy()
    selected["_sort_date"] = pd.to_datetime(dates[mask], errors="coerce")
    selected = selected.sort_values("_sort_date", ascending=False, kind="stable", na_position="last").drop(columns="_sort_date")
    visible = ["Packing Date", "Shipment Date", "Cultivar Name", "Export Name", "Cultivar / Product", "Generated FG Lot No.", "Lot No.",
               "Grade", "Quantity", "Shipped Qty", "Produced Qty", "Waste Qty", "Supplier Name", "Consignee (ปลายทาง)", "Shipping Reason"]
    st.caption(f"{len(selected):,} รายการ · เรียงรายการล่าสุดก่อน · หน่วยกรัม")
    _render_table(selected.head(1000), columns=visible)
    st.download_button("ดาวน์โหลดประวัติ CSV", selected.drop(columns=["Original_Row_Index"], errors="ignore").to_csv(index=False).encode("utf-8-sig"),
                       file_name=f"{sheet_name}.csv", mime="text/csv", key=f"{prefix}_history_download")


