            if st.button("ยืนยันการแพ็ก", key="packing_confirm", type="primary", disabled=invalid or not _can_write(), width="stretch"):
                draft["attempt"] = {"kind": "PACK", "payload": deepcopy({
                    "withdrawals": withdrawals, "outputs": outputs, "packing_date": packing_date,
                    "waste_qty": waste, "note": note, "export_name": export_name,
                })}
