SHEET_NAME = "Trading Data Log"

@st.cache_resource
def init_google_sheets(sheet_name):
    creds = ServiceAccountCredentials.from_json_keyfile_dict(dict(st.secrets["gcp_service_account"]), [
        "https://spreadsheets.google.com/feeds", "https://www.googleapis.com/auth/drive",
    ])
    client = gspread.authorize(creds)
    workbook = client.open(sheet_name)
    main = workbook.get_worksheet(0)
    headers, _ = core.parse_sheet(main.get_all_values(), sheet_name=main.title)
    if headers:
        core.validate_headers(headers, ["Cultivar Name", "Category", "Grade", "Quantity"], sheet_name=main.title)
    def optional(title):
        try:
            return workbook.worksheet(title)
        except gspread.exceptions.WorksheetNotFound:
            return None
    return client, workbook, main, optional("Packing_Records"), optional("Packing_Log"), optional("Shipped_Out_Log")

def can_write():
    return bool(st.session_state.get("portal_can_write", True))


def configure_access():
    access = dict(st.secrets.get("access", {}))
    writable = not bool(access.get("read_only", False))
    if access.get("require_login", False):
        if not st.user.is_logged_in:
            st.title("Thai Stick Trading")
            st.info("กรุณาเข้าสู่ระบบเพื่อเปิดข้อมูล")
            st.button("เข้าสู่ระบบ", on_click=st.login)
            st.stop()
        email = str(st.user.get("email", "")).strip().casefold()
        editors = {str(value).strip().casefold() for value in access.get("editor_emails", [])}
        readers = {str(value).strip().casefold() for value in access.get("reader_emails", [])}
        if email not in editors and email not in readers and "*" not in readers:
            st.error("บัญชีนี้ยังไม่ได้รับสิทธิ์ใช้งาน กรุณาติดต่อผู้ดูแล")
            st.button("ออกจากระบบ", on_click=st.logout)
            st.stop()
        writable = writable and email in editors
    st.session_state["portal_can_write"] = writable


