def clean_quantity(value):
    if not core.text(value):
        return 0.0
    try:
        return float(core.decimal_quantity(value))
    except core.ValidationError:
        return 0.0

DELIVERY_PENDING_VALUES = {"tbc", "to be confirmed", "tbd", "to be decided", "", "nan", "nat", "none"}


def parse_delivery_date(value):
    try:
        parsed = core.parse_date(value, allow_pending=True)
        return pd.Timestamp(parsed) if parsed else pd.NaT
    except core.ValidationError:
        return pd.NaT


def format_df_quantity(frame):
    """Keep quantities numeric so sorting, charts and exports retain their meaning."""
    if frame is None or frame.empty:
        return frame
    result = frame.copy()
    for column in result:
        name = str(column).casefold()
        normalized = re.sub(r"[^a-z0-9]", "", name)
        if normalized == "thaisticklotno":
            result[column] = result[column].map(first_display_lot)
        elif normalized == "generatedfglotno":
            result[column] = result[column].map(fg_display_lot)
        if any(word in name for word in ["date", "วันที่", "timestamp"]):
            def display_date(value):
                if not core.text(value) or core.key(value) in core.PENDING_VALUES:
                    return value
                try:
                    if "timestamp" in name or "created at" in name:
                        return str(value)
                    parsed = core.parse_date(value, allow_pending=True)
                    return parsed.strftime("%d/%m/%Y") if parsed else value
                except core.ValidationError:
                    return value
            result[column] = result[column].apply(display_date)
        numeric = any(word in name for word in ["qty", "quantity", "volume", "available", "shortfall", "demand", "จำนวน", "ยอด", "stock", "inbound", "outbound"])
        ignored = any(word in name for word in ["lot", "id", "name", "note", "remark", "category", "source", "type", "status"])
        if numeric and not ignored:
            nonempty = result[column].dropna().map(core.text)
            nonempty = nonempty[nonempty.ne("")]
            converted = pd.to_numeric(nonempty.str.replace(",", "", regex=False), errors="coerce")
            if not nonempty.empty and converted.notna().all():
                result[column] = pd.to_numeric(result[column].astype(str).str.replace(",", "", regex=False), errors="coerce")
    return result

