def render_section_heading(title, description, eyebrow="", tone="blue"):
    if tone not in {"blue", "slate", "amber", "teal"}:
        tone = "blue"
    st.markdown(
        f'<header class="portal-section portal-section--{tone}">'
        f'<div class="portal-section__eyebrow">{escape(eyebrow)}</div>'
        f'<h2>{escape(title)}</h2><p>{escape(description)}</p></header>',
        unsafe_allow_html=True,
    )


def render_grade_summary(stock_df, total, stock_type):
    names = stock_df["Grade"].astype(str).str.strip().str.upper()
    grades = list(dict.fromkeys(["BIG", "SMALL", "MIX", "F"] + sorted(names.unique())))
    items = [(grade, stock_df.loc[names.eq(grade), "Clean_Qty"].sum()) for grade in grades]
    items.append((f"รวม {stock_type}", total))
    content = [f'<dl class="portal-grade-grid portal-grade-grid--{stock_type.lower()}">']
    for label, quantity in items:
        css = " portal-grade--total" if label == f"รวม {stock_type}" else ""
        content.append(f'<div class="portal-grade{css}"><dt>{escape(str(label))}</dt><dd>{quantity:,.0f} <small>g</small></dd></div>')
    st.markdown("".join(content) + "</dl>", unsafe_allow_html=True)


